<?php
require __DIR__.'/ui.php';role(['admin','gerente']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$pid=(int)$_POST['product_id'];$q=floatval($_POST['qty']);$total=floatval($_POST['total']);$unit=$q>0?$total/$q:0;$p->beginTransaction();$p->prepare("INSERT INTO purchases(supplier_id,product_id,qty,total,unit_cost,reference,purchase_date)VALUES(?,?,?,?,?,?,?)")->execute([$_POST['supplier_id']?:null,$pid,$q,$total,$unit,$_POST['reference'],$_POST['purchase_date']]);$p->prepare("UPDATE products SET stock=stock+?,cost=? WHERE id=?")->execute([$q,$unit,$pid]);$p->commit();go('purchases.php');}$sup=$p->query("SELECT id,name FROM suppliers ORDER BY name")->fetchAll();$pro=$p->query("SELECT id,name FROM products ORDER BY name")->fetchAll();$rows=$p->query("SELECT pu.*,s.name supplier,p.name product FROM purchases pu LEFT JOIN suppliers s ON s.id=pu.supplier_id LEFT JOIN products p ON p.id=pu.product_id ORDER BY pu.id DESC")->fetchAll();page_head('Compras / Histórico de preços');?>
<div class="grid g2"><div class="card"><h2>Registrar compra</h2><form method="post"><?=csrf_field()?><label>Fornecedor</label><select name="supplier_id"><option value="">Sem fornecedor</option><?php foreach($sup as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><label>Produto</label><select name="product_id"><?php foreach($pro as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><div class="grid g3"><div><label>Qtd.</label><input name="qty" type="number" step=".01"></div><div><label>Total</label><input name="total" type="number" step=".01"></div><div><label>Data</label><input name="purchase_date" type="date" value="<?=date('Y-m-d')?>"></div></div><label>Referência / NF</label><input name="reference"><button class="primary">Salvar compra</button></form></div><div class="card kpi"><span>Total comprado</span><strong><?=money(array_sum(array_column($rows,'total')))?></strong></div></div>
<div class="card"><div class="table"><table><tr><th>Data</th><th>Fornecedor</th><th>Produto</th><th>Qtd.</th><th>Unitário</th><th>Total</th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['purchase_date'])?></td><td><?=e($x['supplier'])?></td><td><?=e($x['product'])?></td><td><?=$x['qty']?></td><td><?=money($x['unit_cost'])?></td><td><?=money($x['total'])?></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>